-- Приведение в порядок статьи «Альянс Организации Межзвездного Договора»:
-- флаг союза как обложка и в инфобоксе, содержание, стороны договора флагами со
-- ссылками на их статьи, разбивка договора по статьям.
-- Текст договора не меняется — только структурируется.
update public.pages set
  content = $blk$[{"type":"infobox","id":"aomd1","label":"Союз","title":"Альянс Организации Межзвездного Договора","subtitle":"Организация Межзвездного Договора","image_url":"https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1783449966388-tpp4uk.webp","img_caption":"Флаг Альянса","sections":[{"name":"Основное","rows":[{"key":"Тип","val":"Конфедерация"},{"key":"Депозитарий","val":"Ааа'дукиль"},{"key":"Участников","val":"6"},{"key":"Первоначальных сторон","val":"5"},{"key":"Высший орган","val":"Совет Альянса Звёздной Безопасности"}]}]},{"type":"toc","id":"aomd2"},{"type":"heading","id":"aomd3","text":"ДОГОВАРИВАЮЩИЕСЯ СТОРОНЫ","style":"h-glitch"},{"type":"cols","id":"aomd4","cols":3,"items":["![Ааа'дукиль](https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1781111458184-ivuvu9.jpg)\n**[page:aaa-dukil|Ааа'дукиль]**","**Соединённые Штаты Либертии**","![Ост-Фронтирское Государство](https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1780340046468-rx0vjo.jpg)\n**[page:ost-frontirskoe-gosudarstvo|Ост-Фронтирское Государство]**","![Консорциум Ardsheva](https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1780252286848-ovwu7c.png)\n**[page:konsortsium-ardsheva|Консорциум Ardsheva]**","![ALLMIND Corporation](https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1780478102376-8n2ey5.webp)\n**[page:allmind-corporation|ALLMIND Corporation]**"]},{"type":"heading","id":"aomd5","text":"ПРЕАМБУЛА","style":"h-glitch"},{"type":"text","id":"aomd6","content":"Договаривающиеся Стороны, преисполненные решимости защищать свободу, независимость, общее наследие и цивилизационные ценности своих народов, руководствуясь принципами равноправия, взаимного уважения и коллективной ответственности, сознавая, что в условиях межзвёздной обстановки мир и безопасность могут быть обеспечены только совместными усилиями, желая создать прочную основу для коллективной обороны, экономического процветания и долгосрочной стабильности в освоенном космосе, достигли соглашения о нижеследующем Межзвёздном Договоре:"},{"type":"heading","id":"aomd7","text":"Статья 1. Цели и принципы","style":"h-scan"},{"type":"text","id":"aomd8","content":"Договаривающиеся Стороны обязуются мирно сосуществовать друг с другом, уважать суверенитет, территориальную целостность и политическую независимость друг друга.\n\nСтороны обязуются оказывать друг другу взаимную помощь и поддержку в экономической сфере, в вопросах безопасности и технологического развития. Они будут воздерживаться от любых действий, которые могут нанести ущерб интересам безопасности другой Стороны, и будут активно способствовать укреплению доверия и сотрудничества между собой."},{"type":"heading","id":"aomd9","text":"Статья 1.1.","style":"h-sub"},{"type":"text","id":"aomda","content":"Любые разногласия, возникающие в связи с толкованием или применением настоящего Договора, разрешаются исключительно путём достижения единогласного соглашения Совета Альянса.\n\nРешение Совета Альянса, принятое в соответствии с настоящей статьей, является окончательным и обязательным для всех Сторон Договора."},{"type":"heading","id":"aomdb","text":"Статья 2. Экономическое сотрудничество","style":"h-scan"},{"type":"text","id":"aomdc","content":"Договаривающиеся Стороны будут стремиться к гармонизации своей международной экономической политики, устранению торговых барьеров и противоречий, препятствующих свободному обмену товарами, технологиями и ресурсами.\n\nСтороны обязуются активно содействовать развитию взаимовыгодного экономического сотрудничества, совместным инвестиционным проектам, научным исследованиям и технологическому обмену. Они будут координировать свои усилия в целях обеспечения устойчивого экономического роста и повышения благосостояния своих народов."},{"type":"heading","id":"aomdd","text":"Статья 3. Оборона и коллективная безопасность","style":"h-scan"},{"type":"text","id":"aomde","content":"В интересах более эффективного осуществления целей настоящего Договора Договаривающиеся Стороны, как по отдельности, так и совместно, путём постоянных и действенных самостоятельных усилий, а также взаимной помощи, будут поддерживать и наращивать свой индивидуальный и коллективный потенциал сопротивления вооружённому нападению.\n\nСтороны обязуются развивать военное и техническое сотрудничество, проводить совместные учения, обмениваться разведывательной информацией и совершенствовать системы коллективной обороны для обеспечения неуязвимости Альянса перед внешними угрозами."},{"type":"heading","id":"aomdf","text":"Статья 4. Консультации","style":"h-scan"},{"type":"text","id":"aomdg","content":"Договаривающиеся Стороны будут постоянно консультироваться друг с другом в случае, если, по мнению любой из них, территориальная целостность, политическая независимость или безопасность одной или нескольких Сторон окажутся под угрозой. Такие консультации должны быть начаты незамедлительно по запросу любой из Договаривающихся Сторон."},{"type":"heading","id":"aomdh","text":"Статья 5. Коллективная оборона","style":"h-scan"},{"type":"text","id":"aomdi","content":"Стороны соглашаются, что вооружённое нападение на одну или несколько из них в космосе, на планетах или в любой другой точке контролируемого ими пространства будет рассматриваться как нападение на всех Договаривающихся Сторон.\n\nВ случае такого нападения каждая из Договаривающихся Сторон обязуется немедленно оказать помощь подвергшейся нападению Стороне (или Сторонам) всеми средствами, которые она сочтёт необходимыми, включая применение вооружённой силы, с целью восстановления и поддержания безопасности Альянса."},{"type":"heading","id":"aomdj","text":"Статья 6. Определение вооружённого нападения","style":"h-scan"},{"type":"text","id":"aomdk","content":"Для целей настоящего Договора под вооружённым нападением на одну или несколько Договаривающихся Сторон понимается любое применение силы или угроза силой, направленное против территориальной целостности, политической независимости или безопасности любой из Сторон.\n\nВооружённым нападением считается:\n\nНападение на территорию, планетарные или космические объекты, находящиеся под суверенитетом или контролем любой из Договаривающихся Сторон;\nНападение на вооружённые силы, военные суда, летательные аппараты, орбитальные станции, аванпосты или иные объекты военной инфраструктуры любой из Сторон;\nЛюбая иная форма агрессии, включая неконвенциональные методы ведения войны: диверсии, кибератаки, использование шпионов, террористические акты, саботаж критически важной инфраструктуры, биологическое, химическое или иное скрытое воздействие, направленное против одной из Договаривающихся Сторон.\nЛюбое такое действие, независимо от того, осуществляется ли оно открыто или скрытно, государственными или негосударственными акторами, будет рассматриваться как нападение на всех Договаривающихся Сторон."},{"type":"heading","id":"aomdl","text":"Статья 7. Совместимость с другими международными обязательствами","style":"h-scan"},{"type":"text","id":"aomdm","content":"Каждая Договаривающаяся Сторона заявляет, что ни один из действующих на момент подписания настоящего Договора международных договоров или обязательств не противоречит положениям настоящего Договора.\n\nСтороны обязуются не вступать в какие-либо международные соглашения или союзы, положения которых противоречили бы целям и обязательствам настоящего Договора, и не принимать на себя иные международные обязательства, способные нанести ущерб коллективной безопасности Альянса."},{"type":"heading","id":"aomdn","text":"Статья 8. Совет Альянса и вспомогательные органы","style":"h-scan"},{"type":"text","id":"aomdo","content":"В целях эффективного осуществления целей и положений настоящего Договора учреждается Совет Альянса Звёздной Безопасности. В Совете каждая Договаривающаяся Сторона представлена одним полномочным представителем.\n\nСовет собирается на регулярной основе и по мере необходимости. Он уполномочен рассматривать все вопросы, связанные с выполнением настоящего Договора, принимать решения по текущим и перспективным вопросам безопасности, экономики и сотрудничества.\n\nСовет вправе создавать вспомогательные органы и комитеты по мере необходимости. В частности, Стороны обязуются незамедлительно учредить Комитет Обороны, задачей которого будет координация военных усилий, реализация положений статей 3 и 5 настоящего Договора, планирование совместных операций и развитие коллективных оборонительных возможностей."},{"type":"heading","id":"aomdp","text":"Статья 9. Присоединение новых участников","style":"h-scan"},{"type":"text","id":"aomdq","content":"По единогласному согласию всех Договаривающихся Сторон Совет Альянса может предложить другим государствам или организациям присоединиться к настоящему Договору.\n\nЛюбое государство или организация, получившее такое приглашение, может стать Договаривающейся Стороной путём передачи на хранение Правительству Ааа'дукиля документа о присоединении к настоящему Договору. Правительство Ааа'дукиля незамедлительно уведомляет все Договаривающиеся Стороны о поступлении такого документа."},{"type":"heading","id":"aomdr","text":"Статья 10. Ратификация и вступление в силу","style":"h-scan"},{"type":"text","id":"aomds","content":"Настоящий Договор подлежит ратификации в соответствии с конституционными и внутренними процедурами каждой из Договаривающихся Сторон.\n\nДоговор вступает в силу с момента сдачи на хранение ратификационных грамот всеми пятью первоначальными Договаривающимися Сторонами: Ааа'дукиль, Соединёнными Штатами Либертии, Ост-Фронтирским Государством, Консорциумом Ardsheva и ALLMIND Corporation.\n\nДля любого государства или организации, присоединившегося к Договору после его вступления в силу, настоящий Договор вступает в силу с даты сдачи на хранение документа о присоединении."},{"type":"heading","id":"aomdt","text":"Статья 11. Пересмотр Договора","style":"h-scan"},{"type":"text","id":"aomdu","content":"Договаривающиеся Стороны каждые десять лет, начиная с момента вступления Договора в силу, проводят консультации в рамках Совета Альянса с целью рассмотрения вопроса о возможном пересмотре или дополнении положений настоящего Договора с учётом изменившейся межзвёздной обстановки."},{"type":"heading","id":"aomdv","text":"Статья 12. Выход из Договора","style":"h-scan"},{"type":"text","id":"aomdw","content":"По истечении двадцати лет с момента вступления настоящего Договора в силу любая Договаривающаяся Сторона имеет право выйти из него.\n\nО намерении выйти из Договора Сторона обязана заблаговременно, не менее чем за один год, уведомить в письменной форме все остальные Договаривающиеся Стороны. Выход вступает в силу по истечении указанного срока."},{"type":"heading","id":"aomdx","text":"ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","style":"h-glitch"},{"type":"text","id":"aomdy","content":"Настоящий Договор составлен в пяти экземплярах, каждый из которых имеет одинаковую силу.\n\nДоговор открыт для присоединения других государств и организаций, разделяющих его цели и принципы, при единогласном согласии всех Договаривающихся Сторон."},{"type":"heading","id":"aomdz","text":"Статья 12.1.","style":"h-sub"},{"type":"text","id":"aomd10","content":"Государство или организация, которые грубо нарушают положения настоящего Договора либо осуществляют агрессивные действия против других Договаривающихся Сторон, подлежат лишению членства в Альянсе."}]$blk$,
  image_url = 'https://pgngkkiiopymvrcozvvr.supabase.co/storage/v1/object/public/wiki-images/1783449966388-tpp4uk.webp',
